FROM crm.vwAccounts a
LEFT JOIN reference.vwTaxReturns tr ON a.LatestTaxReturnID = tr.ID
WHERE a.__mj_DeletedAt IS NULL
{% if MinRevenue %} AND ISNULL(tr.TotalRevenue, 0) >= {{ MinRevenue | sqlNumber }} {% endif %}
