  @Name_631b6c0a540e = N'Content Pipeline — Sync'
SET
  @Description_631b6c0a540e = N'Exhaustively walks each selected Content Source (ignoring LastDiscoveredAt), reconciles top-level items that were removed from the source by marking them DeleteStatus = ''Pending'' for the Delete stage, and stamps both LastDiscoveredAt and LastSyncedAt on completion. Selects sources by LastSyncedAt (never by ForceDiscovery, which belongs to Discover); to force a sync on a source, set its LastSyncedAt back or to NULL. Unscheduled by default.'
SET
