SET
  @WorkType_631b6c0a540e = N'Pipeline Stage'
SET
  @ScopeType_631b6c0a540e = N'Filter'
SET
  @ScopeFilter_631b6c0a540e = N'LastSyncedAt IS NULL OR LastSyncedAt < DATEADD(day, -30, GETUTCDATE())'
SET
  @OnChangeEnabled_631b6c0a540e = 0
SET
  @ScheduleEnabled_631b6c0a540e = 0
SET
  @Timezone_631b6c0a540e = N'UTC'
SET
  @OnDemandEnabled_631b6c0a540e = 1
SET
  @SkipUnchanged_631b6c0a540e = 0
SET
  @WatermarkStrategy_631b6c0a540e = N'Checksum'
SET
  @BatchSize_631b6c0a540e = 25
SET
  @MaxConcurrency_631b6c0a540e = 1
SET
  @Configuration_631b6c0a540e = N'{
  "Stages": [
    "Discover"
  ],
  "Options": {
    "Mode": "Sync",
    "Tuning": {
      "MaxSyncRemovalShare": 0.5
    }
  }
}' IF NOT EXISTS (
